create function public.assert_finance_rls(ok boolean,msg text) returns void language plpgsql as $$ begin if not coalesce(ok,false) then raise exception '%',msg; end if; end $$;
set role finance_test_client;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.assert_finance_rls((select count(*) from invoices)=1,'owner invoice isolation');
select public.assert_finance_rls((select count(*) from invoice_items)=1,'owner child isolation');
select public.assert_finance_rls((select count(*) from cash_transactions)=1,'owner cash isolation');
update invoices set status='completed',paid=100 where id='20000000-0000-0000-0000-000000000001';
select public.assert_finance_rls((select paid from invoices where id='20000000-0000-0000-0000-000000000001')=100,'own invoice write');
do $$ declare affected integer; begin
 update invoices set paid=999 where id='20000000-0000-0000-0000-000000000002'; get diagnostics affected=row_count;
 perform public.assert_finance_rls(affected=0,'cross tenant invoice update');
 update invoice_items set quantity=999 where id='30000000-0000-0000-0000-000000000002'; get diagnostics affected=row_count;
 perform public.assert_finance_rls(affected=0,'cross tenant child update');
 update cash_transactions set amount=999; get diagnostics affected=row_count;
 perform public.assert_finance_rls(affected=0,'cash ledger direct update must remain denied');
 delete from invoices; get diagnostics affected=row_count;
 perform public.assert_finance_rls(affected=0,'invoice delete remains denied');
 begin insert into invoices values(gen_random_uuid(),'10000000-0000-0000-0000-000000000002',0,0,'draft'); raise exception 'cross insert accepted'; exception when insufficient_privilege then null; end;
 begin insert into invoice_items values(gen_random_uuid(),'20000000-0000-0000-0000-000000000002',1); raise exception 'cross child insert accepted'; exception when insufficient_privilege then null; end;
 begin insert into cash_transactions values(gen_random_uuid(),'10000000-0000-0000-0000-000000000002',1,'completed'); raise exception 'cross cash insert accepted'; exception when insufficient_privilege then null; end;
end $$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.assert_finance_rls((select count(*) from invoices)=1 and (select total from invoices)=200,'cashier tenant B unaffected');
select public.assert_finance_rls((select count(*) from invoice_items)=1 and (select quantity from invoice_items)=2,'cashier child unchanged');
select public.assert_finance_rls((select count(*) from cash_transactions)=1 and (select amount from cash_transactions)=200,'cashier cash unchanged');
select set_config('request.jwt.claim.sub','',false);
select public.assert_finance_rls((select count(*) from invoices)=0 and (select count(*) from invoice_items)=0 and (select count(*) from cash_transactions)=0,'anonymous cannot read');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000099',false);
select public.assert_finance_rls((select count(*) from invoices)=0 and (select count(*) from cash_transactions)=0,'missing profile denied');
reset role;
select public.assert_finance_rls((select count(*) from pg_policies where schemaname='public' and tablename in ('invoices','invoice_items','cash_transactions'))=8,'no new permissive policies');
select 'FINANCE_RLS_ACCEPTANCE_PASS' as result;
